sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')};items=[]
def add(q,stem,conditions,values,verdicts,reasons,answer,solution,core,knowledge,theories,citations=None,ambiguity='',concept='concept_042',calc=False,figure=False):
 r=by[q];assert len(values)==len(verdicts)==len(reasons)==5
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions,choices={str(i):dict(value=v,verdict=j,reason=why) for i,(v,j,why) in enumerate(zip(values,verdicts,reasons),1)},figures='正誤方向、全条件・数値・単位、候補5肢を原典画像で確認。図なし。組合せ問題では表の全欄を確認。',ambiguity=ambiguity,evidence=[f'extracted/pages/{r["source_year_directory"]}/17_applied_science/page_{p:03}.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],core_concept=core,required_knowledge=knowledge,solution=solution,independent_answer=str(answer),answer_reason=solution,learning_points='モデルの前提を明示し、'+core+'から記述や数値を判定する。',theory_references=['theory:thermo:'+t for t in theories],discipline_id='physics_thermo',concept_id=concept,classification_reason='全条件と全肢を原典画像確認。'+core+'を中心とする熱現象の問題であり、熱力学へ分類する。',calculation=str(calc).lower(),figure=str(figure).lower(),law='false',evaluation=dict(knowledge_novelty='1',reasoning_steps='2' if calc else '1',calculation_load='1' if calc else '0',figure_reading='1' if figure else '0',difficulty='2' if calc or ambiguity else '1',difficulty_reason='物理専攻読者には既知の理論であるが、仕事の向き、条件の省略、量の定義と数値の単位を確認する。'),citations=citations or [],foundationality='high',transferability='high'))
def candidate(q,stem,conditions,values,reasons,answer,solution,core,knowledge,theories,citations=None,**kwargs):
 add(q,stem,conditions,values,['条件に一致' if i==answer else '条件に不一致' for i in range(1,6)],reasons,answer,solution,core,knowledge,theories,citations,**kwargs)

base_values=['温度一定・一定質量の気体の体積は圧力に比例する','圧力一定・一定質量の気体の体積は絶対温度に比例する','外部からの熱と系へされた仕事の和が内部エネルギー増加に等しい','エネルギー変換で関与する全エネルギーの和が保存される','熱は高温から低温へ移り、自然に低温から高温へは移らない']
base_reasons=[r'理想気体なら\(pV=nRT\)であり、固定\(n,T\)では\(V=nRT/p\)と反比例する。比例という記述が誤りである。',r'理想気体又はその近似が成り立つ範囲では固定\(n,p\)により\(V=(nR/p)T\)である。',r'熱を流入正、仕事を系へ入力正とすれば\(\Delta U=Q+W_{\mathrm{on}}\)である。系全体の運動・位置エネルギー変化はこの閉じた熱力学系では考えない。','第一法則のエネルギー保存の内容である。対象系から外へ出るエネルギーを数え落とさない。','第二法則の巨視的な受動的熱移動の方向である。冷凍機は外部仕事を使うので反例ではない。']
for q in ['H23-REG-APPLIED-05','H26-REG-APPLIED-08']:
 add(q,'気体の状態変化、第一法則、第二法則の5記述から最も不適切なものを選ぶ。',{'方向':'最も不適切な記述を選ぶ。','原典の範囲':'一定質量の気体、温度又は圧力一定。理想気体という語は明記されていない。'},base_values,['誤り','理想気体近似で正しい','正しい','正しい','正しい'],base_reasons,1,r'等温の気体の体積と圧力の関係を\(pV=nRT\)で判定する。体積は圧力へ反比例するので1が不適切である。2は理想気体近似のシャルルの法則、3と4はエネルギー保存、5は第二法則である。気体法則は全ての実在気体へ厳密に成立するという主張へ拡張しない。','第一法則の仕事の符号と気体の状態方程式','閉じた系、理想気体近似、絶対温度、熱と仕事の符号、受動的な熱移動。',['firstlaw','ideal','entropy'],['mit_thermo_firstlaw2008'])
order=[2,4,1,0,3]
add('R01-RET-APPLIED-04','第一法則・第二法則と気体の体積変化を判定し、最も不適切な記述を選ぶ。',{'方向':'最も不適切。','原典の範囲':'一定質量の気体。理想気体という語は明記されていない。'},[base_values[i] for i in order],['正しい','正しい','理想気体近似で正しい','誤り','正しい'],[base_reasons[i] for i in order],4,r'1と5は第一法則、2は第二法則、3は理想気体近似の定圧関係である。4の等温体積が圧力に比例するという主張は\(V=nRT/p\)に反するので選ぶ。類似問題と肢の位置が異なるため、以前の番号を転用しない。','気体法則とエネルギー保存の対応','第一法則、第二法則、絶対温度と理想気体近似。',['firstlaw','ideal','entropy'],['mit_thermo_firstlaw2008'])

candidate('H24-REG-APPLIED-08','内部エネルギーの要素と単原子・二原子分子の自由度を、4つの空欄へ対応させる。',{'A':'分子間の力に由来するエネルギー。','B':'分子の熱運動によるエネルギー。','C':'二原子分子ではBに加わる分子内自由度。','D':'同温での分子1個当たりの二原子分子の平均内部エネルギーを、単原子分子と比較する。'},
 ['A運動／B振動・回転／C位置／D小さい','A運動／B振動・回転／C位置／D大きい','A位置／B運動／C振動・回転／D大きい','A位置／B運動／C振動・回転／D小さい','A運動／B位置／C振動・回転／D大きい'],
 ['Aは分子間相互作用の位置エネルギーであり、Bは並進の運動エネルギーである。A〜Cの対応が違う。','大きいというDだけでは足りず、A〜Cの対応が違う。','A位置、B運動、C振動・回転、D大きいという対応に一致する。','二原子分子の回転等が熱的に励起される条件では平均の熱エネルギーが加わる。小さいは逆である。','相互作用の位置エネルギーと並進の運動エネルギーを逆にしている。'],3,r'分子間の力は位置エネルギー、分子の並進は運動エネルギーに対応する。二原子分子には回転と振動があり、励起される自由度は熱エネルギーに寄与するのでA位置・B運動・C振動回転・D大きいの3となる。量子論では低温に振動・回転が凍結し、常に全自由度が等分配されるわけではない。また分子種間の内部エネルギーの絶対零点を比較する問題とは区別する。','分子自由度と内部エネルギーの構成','並進・回転・振動、分子間相互作用、等分配と量子凍結。',['degrees'],['mit_debye2005'],figure=True)

for q in ['H25-REG-APPLIED-08','H28-REG-APPLIED-08']:
 candidate(q,'高温・低温の2熱源で作動する熱機関の最大効率を、機関名と式の組合せで選ぶ。',{'温度':r'絶対温度\(T_H>T_L>0\)。','効率':'外部へ行う仕事／高温熱源から吸収する熱。','空欄':'アは最大効率を与える熱機関名、イはその効率。'},
 [r'カルノー／\((T_H-T_L)/(T_H+T_L)\)',r'フェルマー／\((T_H-T_L)/(T_H+T_L)\)',r'カルノー／\(T_H/(T_H+T_L)\)',r'フェルマー／\((T_H-T_L)/T_H\)',r'カルノー／\((T_H-T_L)/T_H\)'],
 ['機関名は合うが効率の分母は吸熱源の絶対温度であり、温度の和ではない。','機関名と分母の両方が違う。','低温源が高温源に近づくと効率は0へ向かうべきであり、この式はその条件を満たさない。','効率式は合うが機関名が違う。','可逆なカルノー機関とその効率に一致する。'],5,r'熱収支は\(W=Q_H-Q_L\)、可逆サイクルでは\(Q_H/T_H=Q_L/T_L\)である。従って\(\eta=W/Q_H=1-T_L/T_H=(T_H-T_L)/T_H\)となり、カルノー機関とこの式を組み合わせた5である。不可逆損失がある実機の効率はこの上限以下になる。','第二法則が決める熱機関効率の上限','2熱源、可逆性、熱収支、絶対温度、サイクルのエントロピー収支。',['carnot','entropy'],figure=True)

mix_values=['高圧ほど純液体の沸点が上がる','理想気体を断熱膨張させると温度が下がる','同温・同圧で異種気体の混合が自発的に起こる','理想気体の同じ温度上昇には定積の方が定圧より多い熱が必要','理想溶液の各成分の蒸気圧は純成分の蒸気圧×液相モル分率である']
mix_j=['通常の液気平衡で正しい','仕事を外へ行う膨張なら正しい／前提省略','理想的な異種気体で正しい','誤り','理想溶液で正しい']
mix_r=[r'液気平衡で\(dp/dT=L/(T\Delta V)>0\)なので外圧上昇で沸点が上がる。臨界点から離れた通常の沸騰を考える。',r'断熱では\(\Delta U=-W_{\mathrm{out}}\)。正の仕事を外へ行う理想気体は冷えるが、真空への自由膨張なら\(W=0\)で温度は変わらない。膨張だけで冷却は保証されない。',r'非反応の異種理想気体の混合では\(\Delta G=nRT\sum_i x_i\ln x_i<0\)となる。','定圧では膨張仕事も必要であり、理想気体のモル熱容量は定圧が定積よりR大きい。定積の方が多いという記述は逆である。',r'ラウールの法則\(p_i=x_i p_i^*\)である。実在溶液の全組成範囲へ無条件に使う法則ではない。']
amb='原典の断熱膨張の肢は外部仕事又は可逆性を明記しない。理想気体の断熱自由膨張は温度不変であり、この肢も無条件には正しくない。熱容量の逆転肢を最も明確な誤りとして独立選択したが、原典の省略を追加条件で書き換えず部分校正としてAstraへ送る。'
for q,order,ans in [('H25-REG-APPLIED-09',[0,1,2,3,4],4),('H30-REG-APPLIED-06',[1,2,4,0,3],5)]:
 add(q,'理想気体と溶液・相平衡の記述から、最も不適切なものを選ぶ。',{'方向':'最も不適切。','前提の確認':'断熱膨張の肢に外部仕事又は可逆性の指定はない。'},[mix_values[i] for i in order],[mix_j[i] for i in order],[mix_r[i] for i in order],ans,r'同じ理想気体を同じだけ昇温させると定積では\(Q_V=nC_{V,m}\Delta T\)、定圧では\(Q_p=nC_{p,m}\Delta T\)を要し、\(C_{p,m}-C_{V,m}=R>0\)である。定積の方が熱量が大きいという肢'+str(ans)+'を選ぶ。断熱膨張の冷却は正の外部仕事を行う場合に限り、自由膨張という反例があるので解釈疑義を保持する。','熱容量と膨張仕事・相平衡の成立条件','理想気体の熱容量差、断熱と自由膨張、液気平衡、混合エントロピー、ラウールの法則。',['capacity','adiabatic','phase','mixing'],['mit_thermo_adiabatic2008','mit_clapeyron2008','mit_solutions2008'],ambiguity=amb,concept='concept_046')

for q,th,tl,qh,vals,ans in [('H27-REG-APPLIED-08',1500,1200,750,[480,540,600,660,720],3),('R04-REG-APPLIED-06',1000,800,500,[400,450,500,550,600],1)]:
 ql=qh*tl//th
 candidate(q,'カルノーサイクルの吸熱と2熱源の温度から、1サイクルの低温熱源への放熱を求める。',{'高温熱源':str(th)+'K','低温熱源':str(tl)+'K','高温側吸熱':str(qh)+'J','求める量':'低温源へ放出する熱量の正の大きさ。'},[str(x)+'J' for x in vals],['可逆性から得る低温側放熱'+str(ql)+'Jと一致しない。' if x!=ql else '吸熱に低温／高温の温度比を掛けた放熱に一致する。' for x in vals],ans,r'可逆サイクルのエントロピー変化は0なので\(Q_L=Q_HT_L/T_H\)である。数値を代入すると\('+str(qh)+r'\times'+str(tl)+'/'+str(th)+'='+str(ql)+r'\,\mathrm{J}\)となり、'+str(ans)+'を選ぶ。取り出した仕事は吸熱と放熱の差であり、求める放熱と混同しない。','カルノーサイクルの可逆エントロピー収支','絶対温度、吸熱と放熱の正の大きさ、仕事と熱収支。',['carnot'],calc=True)

for q,temp,vals,ans,result in [('H29-REG-APPLIED-06',373,['0.023J','830J','2300J','3100J','8300J'],4,3100),('R06-REG-APPLIED-06',506,['830J','2240J','4200J','8300J','22400J'],3,4200)]:
 candidate(q,'ヒーターで1molの水を一定外圧で全て水蒸気にしたとき、水が外部へ行う仕事を求める。',{'系':'断熱シリンダー内の1molの水と、加熱用ヒーター。','温度':str(temp)+'K','外圧':'0.1MPa一定','仮定':'液体体積を無視、水蒸気は理想気体。','気体定数':'8.3J/(mol・K)','求める量':'水が外部へ行う仕事の正の大きさ。'},vals,['外圧×体積増加=nRTに対して桁又は値が合わない。' if i!=ans else '理想蒸気のpV=nRTに一致する。' for i in range(1,6)],ans,r'外部への体積仕事は\(W_{\mathrm{out}}=p_{\mathrm{ext}}(V_g-V_l)\)である。液体体積を無視し、終状態の理想蒸気に\(p_{\mathrm{ext}}V_g=nRT\)を適用すると\(W_{\mathrm{out}}=1\times8.3\times'+str(temp)+'='+str(round(8.3*temp,1))+r'\,\mathrm{J}\)である。最も近い'+str(result)+'Jの'+str(ans)+'を選ぶ。加熱の総エネルギーや潜熱を問う問題ではない。断熱壁でもヒーターから仕事としてエネルギーが入る。','気化で増えた体積による定圧仕事','一定外圧の仕事、理想気体、液体体積無視、壁からの熱流と電気入力の区別。',['firstlaw','workpaths'],['mit_thermo_firstlaw2008'],calc=True)

candidate('H26-REG-APPLIED-06','水と高温金属球を外界との熱交換なしで接触させ、共通の最終温度を求める。',{'水':'100g、25°C、比熱4.2J/(g・K)','金属':'100g、80°C、比熱0.42J/(g・K)','無視するもの':'ビーカーへの伝熱と外界への熱損失。'},['約30°C','約40°C','約50°C','約60°C','約70°C'],['水420J/Kと金属42J/Kの熱容量で重みを付けると30°Cになる。','金属の熱容量は水の1/10であり、共通温度は水の初期温度にもっと近い。','等質量でも比熱が異なるため単純平均ではない。','水の大きな熱容量を無視している。','水の大きな熱容量を無視している。'],1,r'水が受け取る熱と金属が放出する熱を等置し、\(100\times4.2(T-25)=100\times0.42(80-T)\)とする。整理すると\(420(T-25)=42(80-T)\)、\(462T=13860\)より\(T=30\,{}^\circ\mathrm{C}\)となる。第1候補である。相変化はなく温度差だけなので°Cの差をそのまま使える。','断熱混合のエネルギー保存と熱容量の重み','熱容量mc、比熱と熱容量の違い、相変化なし、熱収支。',['mixheat'],calc=True)

candidate('R02-REG-APPLIED-06','理想気体の定圧・定積4段階変化のうち、第3段階で外部からされる仕事を求める。',{'初期':r'\(p_0=2.0\times10^5\,\mathrm{Pa},V_0=100\,\mathrm{m}^3,T_0=27\,{}^\circ\mathrm{C}\)。','第1段階':'定圧で327°Cへ加熱。','第2段階':'定積で27°Cへ冷却。','第3段階':'定圧で−123°Cへ冷却。','第4段階':'定積で27°Cへ加熱。','求める量':'第3段階で気体へされる仕事。'},[r'\(1\times10^6\,\mathrm{J}\)',r'\(2\times10^6\,\mathrm{J}\)',r'\(5\times10^6\,\mathrm{J}\)',r'\(1\times10^7\,\mathrm{J}\)',r'\(2\times10^7\,\mathrm{J}\)'],['圧縮仕事の計算値より1桁小さい。','圧縮の温度幅と気体量の両方を反映していない。','第3段階の体積差100m³と圧力10^5Paの積の半分である。','圧力10^5Pa×減少体積100m³に一致する。','第3段階へ初期圧力2×10^5Paをそのまま使った値である。'],4,r'温度を約300,600,300,150Kとする。第1段階で体積は200m³、第2段階で圧力は\(1.0\times10^5\,\mathrm{Pa}\)になる。第3段階は150Kへの定圧冷却なので体積は100m³となる。気体へされる仕事は\(W_{\mathrm{on}}=p(V_{\mathrm{start}}-V_{\mathrm{end}})=10^5(200-100)=10^7\,\mathrm{J}\)、第4候補である。体積は100m³であり100mLではない。','定圧仕事の経路依存と絶対温度の換算','一定気体量のpV/T保存、定積p∝T、定圧V∝T、圧縮仕事の正符号。',['workpaths','ideal'],calc=True)
candidate('R07-REG-APPLIED-06','理想気体を定圧・定積で4段階に変化させ、第3段階の外部からの仕事を求める。',{'初期':r'\(p_0=5.0\times10^3\,\mathrm{Pa},V_0=120\,\mathrm{m}^3,T_0=27\,{}^\circ\mathrm{C}\)。','第1段階':'定圧で227°Cへ加熱。','第2段階':'定積で27°Cへ冷却。','第3段階':'定圧で−73°Cへ冷却。','第4段階':'定積で27°Cへ加熱。','求める量':'第3段階で気体へされる仕事。'},[r'\(2\times10^5\,\mathrm{J}\)',r'\(5\times10^5\,\mathrm{J}\)',r'\(1\times10^6\,\mathrm{J}\)',r'\(2\times10^6\,\mathrm{J}\)',r'\(5\times10^6\,\mathrm{J}\)'],['nR=初期pV/Tと圧縮温度幅100Kの積に一致する。','原典の圧力の指数と圧縮温度幅を用いた結果と合わない。','計算値の5倍であり、段階の温度と圧力を区別していない。','計算値より1桁大きい。初期圧力の指数は3である。','圧力の指数又は体積変化の計算が一致しない。'],1,r'絶対温度を約300,500,300,200Kとする。気体量を\(nR=p_0V_0/T_0=(5.0\times10^3)120/300=2000\,\mathrm{J/K}\)と置く。第3段階の定圧圧縮仕事は\(W_{\mathrm{on}}=-nR\Delta T=2000(300-200)=2.0\times10^5\,\mathrm{J}\)、第1候補である。途中状態はV=200m³、p=3000Pa、終体積400/3m³であり、pΔVからも同じ値になる。','状態方程式から気体量を消去する定圧仕事','pV=nRT、絶対温度、定圧仕事−nRΔT、仕事の向き。',['workpaths','ideal'],calc=True)

candidate('H30-REG-APPLIED-07','室温での熱伝導率を4材料について大きい順に並べる。',{'条件':'室温で通常のバルク材料の代表的な熱伝導率を比較する。'},['ダイヤモンド→銅→鉄鋼→板ガラス','ダイヤモンド→鉄鋼→銅→板ガラス','銅→鉄鋼→ダイヤモンド→板ガラス','銅→鉄鋼→板ガラス→ダイヤモンド','銅→ダイヤモンド→鉄鋼→板ガラス'],['代表的な室温の大小関係に一致する。','鉄鋼と銅が逆である。','高品質のバルクダイヤモンドを金属より下に置いている。','バルクダイヤモンドを最小にしている。','バルクダイヤモンドと銅が逆である。'],1,'ダイヤモンドの結晶格子は室温で熱をよく運び、高品質バルクでは銅より熱伝導率が大きい。通常の銅は鉄鋼より大きく、板ガラスは小さい。従ってダイヤモンド→銅→鉄鋼→板ガラスの1である。電気絶縁体なら熱伝導率も低い、という推論はダイヤモンドでは成立しない。結晶欠陥・粒径・純度・合金種で値は変わるので、全ての試料に同じ序列を断定しない。','熱を運ぶ電子と格子振動・材料依存','熱伝導率と電気伝導率の区別、室温、バルク材料、純度と欠陥。',['transport'],['aist_metal_thermal','wang_sun_diamond2024','agc_glass_thermal'])
add('R01-REG-APPLIED-06','熱伝導、計測、熱起電力の記述から最も不適切なものを選ぶ。',{'方向':'最も不適切。'},['ピラニ真空計は吸着による気体圧力の変化で熱伝導率を求める','固体の熱伝導はフォノンによるエネルギー移動を伴う','Alの熱伝導率はFeより大きい','異種金属の接合部の温度差は導線方向の電場を生む熱起電力に関係する','フーリエの法則では熱流密度が温度勾配の大きさに比例する'],['誤り','正しい','通常の室温材料で正しい','正しい','線形等方近似で正しい'],['ピラニ計は加熱フィラメントから気体へ逃げる熱の圧力依存性を、抵抗や加熱電力で読み圧力へ換算する。吸着を測って熱伝導率を求める説明ではない。','結晶格子の振動励起がエネルギーを運ぶ。金属では伝導電子の寄与もあるので、唯一の担体とは考えない。','産総研の室温付近のデータではAlは226〜237、Feは72〜80.4W/(m・K)程度であり大小が合う。','ゼーベック効果である。異種材料の温度依存する熱電能の差を利用する。','熱は温度が下がる方向へ流れるのでベクトルとしては温度勾配と逆向きである。'],1,'1は計測の対象と手段を取り違えている。ピラニ計は気体の熱移動による加熱線の熱損失を利用して真空の圧力を測る。2〜5は各材料・線形応答の条件で妥当であり、吸着による圧力変化から熱伝導率を求めるという1を選ぶ。','熱輸送を利用した圧力計測と熱電効果','ピラニ計のフィラメント、フォノン、電子、熱電能、フーリエの法則。',['transport','measurement'],['ulvac_pirani','aist_metal_thermal'])
add('R04-REG-APPLIED-07','熱電対、金属の伝導、多孔質、放射について最も不適切な記述を選ぶ。',{'方向':'最も不適切。'},['異種金属又は合金2種で温度計測できる','金属の熱伝導率／電気伝導率は極低温を除き絶対温度へ比例する','ダイヤモンドの熱伝導率は銀より小さい','空孔にある気体は熱を運びにくく、多孔質材料は熱伝導率が低い','熱放射は電磁波でのエネルギー移動である'],['正しい','通常の金属の電子輸送近似で正しい','通常のバルク比較で誤り','一般的な断熱材料で正しい','正しい'],['熱電対は2種の材料の熱電能の差から温度差を電圧へ変換する。','ウィーデマン＝フランツ則の電子輸送の関係である。散乱の機構や格子熱伝導の大きさによって厳密には変わる。','高品質バルクダイヤモンドは銀より大きい。金属の電気伝導の序列から熱伝導の序列を全材料へ拡張できない。','固体の連続した伝導経路を減らし気体の低い伝導率を利用する。ただし大きな孔の対流や高温の放射は別に評価する。','媒体の巨視的移動が必要な対流とは区別する。'],3,'典型的なバルクダイヤモンドは室温で銀より熱伝導率が大きいので3が不適切である。他の肢は熱電対、金属の電子輸送の近似、多孔質断熱、熱放射に対応する。熱伝導の担体は電子だけではなく、ダイヤモンドでは格子振動が重要である。','熱伝導と電気伝導の関係の適用範囲','熱電対、ウィーデマン＝フランツ則、フォノン、多孔質の有効伝導、電磁放射。',['transport','measurement'],['aist_metal_thermal','wang_sun_diamond2024'])

add('R03-REG-APPLIED-07','電子・格子・気体の比熱と相転移の5記述から最も不適切なものを選ぶ。',{'方向':'最も不適切。','記号':'Rは気体定数。','原典の省略':'格子比熱は「室温又はそれ以上」、二原子分子は「比較的低い温度」、固体の熱容量差は「100K以下」と記す。物質や固有温度は指定しない。'},['電子比熱はフェルミ準位の状態密度と温度に反比例する','格子モル比熱は室温又はそれ以上の高温で3Rとなる','二原子分子の定圧モル比熱は比較的低温で定積の7/5倍である','二次相転移では不連続な変化を伴う異常比熱が現れる','固体の定積・定圧モル比熱の差は100K以下で無視できるほど小さい'],['誤り','デバイ温度に比べ高温なら近似的に正しい／原典の範囲に疑義','回転励起・振動凍結の範囲で正しい','二次相転移の比熱異常として妥当','通常の固体での低温近似／物質依存'],[r'通常の縮退電子では\(C_e=(\pi^2/3)k_B^2D(E_F)T\)で、状態密度と温度へ比例し、反比例ではない。',r'デュロン＝プティ則は\(T\gg\Theta_D\)の古典極限である。室温というだけでは高いデバイ温度を持つ物質には適用できない。',r'並進3・回転2自由度なら\(C_{V,m}=5R/2\)、\(C_{p,m}=7R/2\)で比は7/5である。回転まで凍結する極低温や振動の励起される高温では違う。','ギブズエネルギーの二階微分に異常が出る。有限跳びや発散があり、全ての連続相転移が同じ形の跳びを持つとは限らない。',r'\(C_p-C_V=TV\alpha_V^2/\kappa_T\)であり低温では一般に小さくなる。ただし100Kという数値だけから全物質で無視可能と断定はできない。'],1,r'状態密度\(D(E_F)\)と温度Tへの比例が電子比熱の特徴であり、反比例とする1を最も明確な誤りとして選ぶ。2は高温の古典極限、3は回転のみ励起、4は転移の比熱異常、5は小さな熱膨張に対応する。原典の温度範囲は物質固有の励起温度を記さないため、2・3・5を全材料・全低温に成り立つ法則として説明しない。','量子励起の温度尺度と比熱','電子比熱γT、デバイ温度、二原子分子の自由度、相転移、熱膨張と圧縮率。',['degrees','solidcapacity','phase'],['mit_electronic_heat2012','mit_debye2005'],ambiguity='1の反比例は明確な誤りで独立選択1。2の室温以上で3Rという一律範囲は高デバイ温度物質で成立しない。3の低温は回転励起・振動凍結の中間範囲、5の100Kも材料依存である。原典の限定不足をAstraの解釈査読対象とし、部分校正を保持する。')

candidate('R04-REG-APPLIED-11','水の三重点を既知として、富士山頂の大気圧下の沸点を求めるための理論式を選ぶ。',{'既知のもの':'水の三重点の温度と蒸気圧、山頂の大気圧。','求める対象':'純水の液気共存温度。数値の沸点を答える問題ではない。'},['ボルンの式','クラウジウス＝クラペイロンの式','ファントホッフの式','プランクの式','レイリー＝ジーンズの式'],['イオンの静電的な溶媒和などを扱う式で、直接の液気共存曲線ではない。','液気共存の圧力と温度の関係を与える。','平衡定数の温度依存を扱うが、この液気平衡を直接記す名称としてはクラウジウス＝クラペイロンが適切である。','黒体放射のスペクトルを扱う。','黒体放射の古典的な低周波近似を扱う。'],2,r'沸点では蒸気圧が外圧に等しく、液気共存曲線をたどればよい。関係式は\(dp/dT=L/[T(V_g-V_l)]\)で、蒸気を理想気体とし液体体積を無視すると\(d\ln p/dT=L_m/(RT^2)\)となる。クラウジウス＝クラペイロンの式の2を選ぶ。有限区間の数値を求めるには潜熱やその温度依存なども必要であり、指定されない山頂の沸点を補わない。','相共存曲線と圧力による沸点の変化','相平衡の化学ポテンシャル一致、潜熱、蒸気圧、理想蒸気近似。',['phase'],['mit_clapeyron2008'],concept='concept_046')
add('R04-REG-APPLIED-17','実在気体の圧縮係数と分子間力の記述から最も不適切なものを選ぶ。',{'方向':'最も不適切。','定義':'同温・同圧で実在気体のモル体積を理想気体のモル体積で割った比を圧縮係数とする。'},['高圧では理想気体の法則から外れる','低圧では分子間力の影響が小さい','圧縮係数は同温同圧の実在／理想のモル体積比である','ファンデルワールス式は引力と分子の大きさを考慮する','圧縮係数は温度や圧力に関係なく1より大きい'],['一般に正しい','低密度極限で正しい','正しい','正しい','誤り'],['分子の占有体積や相互作用が無視できず、低密度の理想近似から外れやすい。','密度が下がると分子間相互作用による圧力への補正は小さくなる。',r'理想モル体積は\(RT/p\)なので比は\(Z=pV_m/(RT)\)である。',r'\((p+a/V_m^2)(V_m-b)=RT\)でaが引力、bが排除体積の補正を表す。',r'引力が優勢なら\(Z<1\)、排除体積が優勢なら\(Z>1\)になり得る。低密度では1へ近づく。'],5,r'圧縮係数を\(Z=pV_m/(RT)\)と定義する。引力は同温同密度で圧力を下げ、分子の大きさは圧力を上げる方向へ効く。従ってZは1の上下いずれにもなり得て、温度・圧力にかかわらず1より大きいという5は誤りである。','圧縮係数による理想気体からのずれの表現','モル体積、理想気体極限、引力と排除体積、ファンデルワールス式。',['realgas'])
add('R05-REG-APPLIED-06','相転移の次数、熱力学量、強磁性、過冷却の記述から最も不適切なものを選ぶ。',{'方向':'最も不適切。','対象':'融解・気化と連続相転移の通常の分類。'},['融解と気化は一次相転移である','一次相転移ではエントロピーが不連続に変わる','二次相転移では熱容量は連続に変わる','鉄の強磁性から常磁性への転移は二次相転移である','液体や気体を平衡転移温度より冷やしても相変化しない過冷却がある'],['臨界点から離れた相共存で正しい','正しい','誤り','通常の零磁場のキュリー転移として正しい','正しい'],['融解・気化は潜熱を伴う通常の一次転移である。液気臨界点で相の区別がなくなる場合は別である。',r'潜熱Lと転移温度Tにより\(\Delta S=L/T\)でエントロピーの跳びがある。','二次転移ではギブズエネルギーの一階微分は連続でも、比熱のような二階微分に跳びや発散が出る。','磁化という秩序変数が零磁場で連続に消える転移であり、比熱には異常が現れる。','新相の核生成の障壁などで準安定状態が続く。平衡の共存温度そのものが変わったとの意味ではない。'],3,r'相転移の次数は自由エネルギーの微分の性質で整理する。一次ではエントロピーなど一階微分が跳び、二次・連続転移では比熱など二階微分が異常を示す。熱容量は連続であると一律に述べる3が不適切である。過冷却は平衡相図と変化の速度を区別する例である。','自由エネルギーの微分から見る相転移と準安定状態','ギブズエネルギー、潜熱、エントロピー、熱容量、秩序変数、核生成。',['phase'])

